package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DecimalWrittenDivisionTest {
 @Test public void exactSupplyHasAllBoundariesAndAtMostFourWrittenColumns(){int count=0;for(int q=0;q<=9999;q++)for(int d=1;d<=12;d++){Question x=DecimalWrittenDivision.make(q,d);assertEquals(Rational.of(q,100),Expression.number(x.answers[0]));assertTrue(new Checker().check(x,List.of(),List.of(x.answers[0])).correct());HelpPlan p=HelpPlan.forQuestion(x);assertTrue(p.size()>=11&&p.size()<=23);assertFalse(p.canTransfer());count++;}assertEquals(120000,count);}
 @Test public void publicColumnsValidateEveryOperationAndReferencesUseOnlyLearnerEntries(){Question q=DecimalWrittenDivision.make(264,12);q.expression="poison";q.answers=new String[]{"999"};HelpPlan p=HelpPlan.forQuestion(q);List<String> v=List.of("31.68","12","2","100","3168","31","2","24","7","76","6","72","4","48","4","48","0","264","2.64");assertEquals(19,p.size());for(int i=0;i<v.size();i++){assertTrue("stage"+i,p.step(i).accepts(v.get(i)));assertFalse(p.step(i).accepts(""));}assertFalse(p.step(9).accepts("75"));assertFalse(p.step(10).accepts("7"));assertFalse(p.step(11).accepts("73"));assertFalse(p.step(12).accepts("5"));for(int stage=5;stage<19;stage++)assertTrue(DecimalWrittenDivision.references(q,stage,v.subList(0,stage)).size()<=2);assertTrue(DecimalWrittenDivision.references(q,5,List.of()).isEmpty());var refs=DecimalWrittenDivision.references(q,9,v.subList(0,9));assertEquals("6",refs.get("내릴 숫자 a = "));assertEquals("7",refs.get("이전 나머지 r = "));assertFalse(refs.containsValue("76"));assertEquals("264",DecimalWrittenDivision.references(q,17,v.subList(0,17)).get("입력한 몫 숫자 = "));}
 @Test public void gradeLinkFreshnessAndDraftRestore(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(DecimalWrittenDivision.ID,6));Generator g=new Generator(new Random(94));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(DecimalWrittenDivision.ID,recent,false,GlobalCurriculum.limits(pack.id,DecimalWrittenDivision.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}Question q=DecimalWrittenDivision.make(264,12);HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft draft=new HelpPlan.Draft();draft.questionId=q.id;draft.teachingVersion=q.studyGuide.teachingVersion;draft.entries=new ArrayList<>(List.of("31.68","12","2","100","3168","31","2","24","7"));draft.stage=9;assertEquals(9,p.restore(draft,q.id).stage);Learning.Profile profile=new Learning.Profile();profile.countryCode="KR";profile.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(profile).stream().noneMatch(x->DecimalWrittenDivision.supports(x.id)));}
}
